/**
 * data/b3/syllable-reading.js — the G1-306 `syllable-reading` bank (nt20-C).
 *
 * EN block hand-authored 2026-09-14 from approved-words-en.json (texPool:
 * 'TeX' in sources_agreed — every printed onset|rime boundary is TeX-agreed),
 * count === 1, /^\p{L}+$/u, colour picture via lib/b3-picture-index.js. The
 * word lists per row are the COMPLETE set the data yields for that rime under
 * those filters (qa/verify-b3-syllable-reading.js re-derives them from the
 * approved file and diffs — an omitted or invented word fails the gate).
 * The 10 non-EN blocks are generated by tools/apply-b3-locale.js from the
 * native panels' drafts (data/ is gitignored; the reviewer force-adds).
 *
 * Shape (design file §5; the ONE apparatus for all three rebuild shapes):
 *   shape      'syllable' (S rows) | 'rime' (R rows) | 'soundout' (B rows)
 *   exemplar   the row id a unit-less build() uses (unitAxis fallback)
 *   rows       S: `units[]`  R: `rimes[]`  B: `units[]` — ordered; the carpet
 *              at difficulty d = the d.carpetRows consecutive rows from the unit
 *   row        { id, label, cells[], readOnly[]?, rime?, words[] }
 *              cells    printed verbatim, in reading order; R cells 'onset|rime'
 *              readOnly cells that no picture uses (R: consonant onset + rime,
 *                       NOT pictured) — read, never solved
 *              words    { key (vocabKey), word (display form), unit } — unit =
 *                       what the child WRITES: S split[0] · R the onset ·
 *                       B the whole word; S words also carry `split`, B `chunks`;
 *                       optional `pictureTheme` PINS the picture to one cached
 *                       theme dir when another dir's art is not the word
 *                       (opened 2026-09-14: kitchen tools/pan is a lidded pot,
 *                       around the house/rug a polka-dot frame)
 *   simpleRime R: the short-vowel rime regex a `structure:'simple'` page allows
 *              (single short vowel + consonants; no r-controlled, no long vowel)
 *   ban / whitelist / refuse / sepMode / strings — per the design file
 */
'use strict';
const SYLLABLE_READING = {
  en: {
    shape: 'rime',
    exemplar: 'an',
    casing: 'lower',
    strictPool: null,
    // R rows in reading order. d2 carpet = the unit row + the next one
    // (exemplar 'an' → -an / -at, 8 pictured words); d1 = the unit row alone
    // (-an is the only rime with 5 pictured words, hence first); d3 = three rows.
    rimes: [
      { id: 'an', label: '-an', rime: 'an',
        cells: ['c|an', 'f|an', 'p|an', 'v|an', 'sw|an'], readOnly: [],
        words: [
          { key: 'can', word: 'can', unit: 'c' },
          { key: 'fan', word: 'fan', unit: 'f' },
          { key: 'pan', word: 'pan', unit: 'p', pictureTheme: 'around the house' },   // kitchen tools/pan is a lidded POT
          { key: 'van', word: 'van', unit: 'v' },
          { key: 'swan', word: 'swan', unit: 'sw' },
        ] },
      { id: 'at', label: '-at', rime: 'at',
        cells: ['b|at', 'c|at', 'h|at', 'm|at', 's|at'], readOnly: ['mat', 'sat'],
        words: [
          { key: 'bat', word: 'bat', unit: 'b' },
          { key: 'cat', word: 'cat', unit: 'c' },
          { key: 'hat', word: 'hat', unit: 'h' },
        ] },
      { id: 'ock', label: '-ock', rime: 'ock',
        cells: ['cl|ock', 'l|ock', 'r|ock', 's|ock', 'd|ock'], readOnly: ['dock'],
        words: [
          { key: 'clock', word: 'clock', unit: 'cl' },
          { key: 'lock', word: 'lock', unit: 'l' },
          { key: 'rock', word: 'rock', unit: 'r' },
          { key: 'sock', word: 'sock', unit: 's' },
        ] },
      { id: 'ug', label: '-ug', rime: 'ug',
        cells: ['j|ug', 'm|ug', 'r|ug', 'sl|ug', 'b|ug'], readOnly: ['bug'],
        words: [
          { key: 'jug', word: 'jug', unit: 'j' },
          { key: 'mug', word: 'mug', unit: 'm' },
          { key: 'rug', word: 'rug', unit: 'r', pictureTheme: 'furniture' },           // around the house/rug reads as a polka-dot frame
          { key: 'slug', word: 'slug', unit: 'sl' },
        ] },
      { id: 'og', label: '-og', rime: 'og',
        cells: ['d|og', 'fr|og', 'l|og', 'f|og', 'h|og'], readOnly: ['fog', 'hog'],
        words: [
          { key: 'dog', word: 'dog', unit: 'd' },
          { key: 'frog', word: 'frog', unit: 'fr' },
          { key: 'log', word: 'log', unit: 'l' },
        ] },
      { id: 'and', label: '-and', rime: 'and',
        cells: ['h|and', 's|and', 'w|and', 'b|and', 'l|and'], readOnly: ['band', 'land'],
        words: [
          { key: 'hand', word: 'hand', unit: 'h' },
          { key: 'sand', word: 'sand', unit: 's' },
          { key: 'wand', word: 'wand', unit: 'w' },
        ] },
      { id: 'ed', label: '-ed', rime: 'ed',
        cells: ['b|ed', 'sl|ed', 'w|ed', 'f|ed', 'sh|ed'], readOnly: ['wed', 'fed', 'shed'],
        words: [
          { key: 'bed', word: 'bed', unit: 'b' },
          { key: 'sled', word: 'sled', unit: 'sl' },
        ] },
    ],
    blends: ['bl', 'cl', 'fl', 'gl', 'pl', 'sl', 'br', 'cr', 'dr', 'fr', 'gr', 'tr', 'st', 'sw'],
    // a `structure:'simple'` R page: one short vowel then consonants; `r` is
    // absent from the class so every r-controlled rime (-ar, -orn) fails, and
    // a second vowel letter or a final e (long-vowel families) fails too
    simpleRime: /^[aeiou][bcdfghjklmnpqstvwxz]+$/,
    // `red` is approved, count 1, TeX and pictured — but its only picture (colors/red) is a
    // red DROP, which a six-year-old reads as blood or a drop, not as the word; opened 2026-09-14
    ban: ['red'],
    whitelist: {},
    refuse: { finalMuteE: false },
    sepMode: 'hyphen',
    strings: {
      'G1-306': {
        title: 'Word Families: Read and Write',
        instruction: 'Read every word on the carpet out loud. Say each picture word, find it on the carpet, then write its beginning on the line before the ending.',
      },
    },
  },
};
module.exports = { SYLLABLE_READING };
